import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"RGW Refactoring Meeting 2022-09-28","description":"","frontmatter":{"title":"RGW Refactoring Meeting 2022-09-28","date":"2022-09-28T00:00:00.000Z","updated":"2022-09-30T00:00:00.000Z","tags":["Ceph分布式存储","性能优化","模块化","RGW","性能计数器"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/RGW_Refactoring_Meeting_2022-09-28.md","filePath":"posts/2022/RGW_Refactoring_Meeting_2022-09-28.md","lastUpdated":1780460162000}'),p={name:"posts/2022/RGW_Refactoring_Meeting_2022-09-28.md"};function n(o,l,s,_,r,u){return e(),t("div",null,[...l[0]||(l[0]=[a("<p>会议纪要：</p><ol><li><p>讨论主题：Ceph分布式存储系统的RGW模块性能指标优化和模块化进程。</p><ul><li>主要关注点：如何管理和优化大量的性能计数器，以及处理模块化过程中遇到的问题。</li></ul></li><li><p>参与者：</p><ul><li>Yvonne（Ceph导出器开发者）</li><li>Ilya（RBD领导）</li><li>Casey（参与讨论并提出问题和建议）</li></ul></li><li><p>关键议题：</p><ul><li>性能计数器的管理和优化：Yvonne提及支持标签化性能计数器的工具，而Ilya认为不需要过多标记的性能计数器。Casey询问了性能计数器爆炸性增长的问题及如何进行过滤。</li><li>自动化策略的探讨：Casey提出一个自动化的方法来识别“热用户”和“热存储桶”，从而只启用被认定为“热”的标记性能计数器。</li><li>模块化进程：Ilya讨论了管理admin APIs时的模块化进程，并提出了在S3层操作中分离pub/sub操作的问题。</li></ul></li><li><p>决定事项：</p><ul><li>短期内，将重点放在优化现有的性能计数器管理上，不立即实施复杂的自动化策略。</li><li>长期解决方案可能需要构建一个新的系统，该系统能够根据用户的需求动态地启用或禁用特定的性能计数器。</li><li>需要进一步讨论如何处理Prometheus无法处理大量性能计数器的问题。</li></ul></li><li><p>后续行动计划：</p><ul><li>Yvonne将继续完善她的标签化性能计数器工具，并在下一周展示新版接口。</li><li>Ilya和团队将继续进行模块化进程，特别是解决pub/sub操作的分离问题。</li><li>Casey将探索自动化策略，以更有效地管理性能计数器。</li></ul></li><li><p>其他讨论：</p><ul><li>讨论了HTTP 3前端原型的开发和测试，欢迎感兴趣的成员参与。</li></ul></li><li><p>结论：</p><ul><li>会议围绕Ceph的性能优化和模块化进程进行了深入讨论，确定了短期和长期的行动计划，并鼓励团队成员继续在这些领域进行探索和开发。</li></ul></li></ol>",2)])])}const R=i(p,[["render",n]]);export{d as __pageData,R as default};
